import json
from pathlib import Path
import pandas as pd, yaml
ROOT=Path(__file__).resolve().parents[1]; df=pd.read_csv(ROOT/'data/financials.csv'); peers=yaml.safe_load((ROOT/'config/peers.yml').read_text(encoding='utf-8'))['peers']
def rec(k): return df[df.report_type==k].where(pd.notna(df),None).to_dict('records') if not df.empty else []
payload={'annual':rec('annual'),'half_year':rec('half-year'),'quarterly':rec('quarterly'),'peers':peers}
html="""<!doctype html><html lang='ko'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>SK hynix DART Financial Dashboard</title><script src='https://cdn.plot.ly/plotly-2.35.2.min.js'></script><style>:root{--bg:#f7f3ec;--card:#fffdf9;--line:#e7dfd3;--ink:#403a34;--muted:#837a70}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,'Noto Sans KR',sans-serif}.wrap{max-width:1400px;margin:auto;padding:34px 22px 70px}.hero,.panel,.card{background:var(--card);border:1px solid var(--line);border-radius:22px}.hero{padding:34px;margin-bottom:20px;background:linear-gradient(135deg,#fffdf8,#eee4d4)}.kicker{font-size:13px;color:var(--muted);letter-spacing:.1em}.title{font-size:42px;font-weight:750;margin:8px 0}.sub,p,.label{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.card{padding:20px}.value{font-size:27px;font-weight:750;margin-top:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{padding:18px;margin-top:18px}.panel h2{font-size:19px;margin:0 0 5px}.chart{height:390px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:16px}table{width:100%;border-collapse:collapse;min-width:1050px;background:#fff}th,td{padding:10px;border-bottom:1px solid #eee8df;text-align:right;font-size:12px;white-space:nowrap}th:first-child,td:first-child,th:nth-child(2),td:nth-child(2){text-align:left}th{background:#f4eee5}a.badge{display:inline-block;padding:7px 11px;border-radius:999px;background:#efe4d1;color:#665845;text-decoration:none;font-size:12px}@media(max-width:900px){.cards,.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.cards,.grid{grid-template-columns:1fr}.title{font-size:32px}}</style></head><body><main class='wrap'><section class='hero'><div class='kicker'>DART · OPEN DART · FINANCIAL DATA</div><div class='title'>SK hynix Financial Dashboard</div><div class='sub'>2010–present · Annual / Half-year / Quarterly · OpenDART 기반 자동 업데이트</div><a class='badge' href='https://github.com/HSC-Class02/SB_SKhynix' target='_blank'>GitHub Repository →</a></section><div id='cards' class='cards'></div><div class='grid'><section class='panel'><h2>매출 · 영업이익 · 순이익</h2><p>연간 주요 손익계정 추이</p><div id='profit' class='chart'></div></section><section class='panel'><h2>주요 수익성 지표</h2><p>영업이익률 · ROE · ROA</p><div id='ratio' class='chart'></div></section></div><section class='panel'><h2>Annual</h2><p>사업보고서</p><div id='annual'></div></section><section class='panel'><h2>Half-year</h2><p>반기보고서</p><div id='half'></div></section><section class='panel'><h2>Quarterly</h2><p>분기보고서</p><div id='quarter'></div></section><section class='panel'><h2>Domestic Peer Firms</h2><p>국내 반도체 산업·공급망 관점의 참고 기업</p><div id='peers'></div></section><section class='panel'><p>데이터 주의사항: 2015년 이후는 XBRL 재무제표 API를 우선 사용하고, 2010~2014년은 DART 원문 기반 legacy parser를 사용합니다. 정정공시가 제출되면 수치가 변경될 수 있으므로 중요한 분석에는 원문 보고서를 함께 확인하세요.</p></section></main><script>const D=__DATA__;const money=['revenue','operating_income','net_income','total_assets','total_liabilities','total_equity','current_assets','current_liabilities','cash','ppe','receivables','inventory','cfo'];const pct=['operating_margin','net_margin','roe','roa'];function f(v){return v==null||v===''?'—':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:1})}function p(v){return v==null?'—':(Number(v)*100).toFixed(1)+'%'}function cards(){let a=D.annual.filter(x=>x.revenue!=null).sort((x,y)=>x.year-y.year),x=a[a.length-1]||{};let z=[['최근 연도',x.year??'—'],['매출액',f(x.revenue)],['영업이익',f(x.operating_income)],['영업이익률',p(x.operating_margin)]];document.getElementById('cards').innerHTML=z.map(i=>`<div class='card'><div class='label'>${i[0]}</div><div class='value'>${i[1]}</div></div>`).join('')}function charts(){let a=D.annual.filter(x=>x.year!=null).sort((x,y)=>x.year-y.year);let base={margin:{t:15,r:20,b:45,l:55},legend:{orientation:'h'},paper_bgcolor:'transparent',plot_bgcolor:'transparent',hovermode:'x unified'};Plotly.newPlot('profit',[['revenue','매출액'],['operating_income','영업이익'],['net_income','당기순이익']].map(q=>({x:a.map(x=>x.year),y:a.map(x=>x[q[0]]),name:q[1],type:'scatter',mode:'lines+markers'})),base);Plotly.newPlot('ratio',[['operating_margin','영업이익률'],['roe','ROE'],['roa','ROA']].map(q=>({x:a.map(x=>x.year),y:a.map(x=>x[q[0]]==null?null:Number(x[q[0]])*100),name:q[1],type:'scatter',mode:'lines+markers'})),{...base,yaxis:{ticksuffix:'%'}})}const cols=[['year','연도'],['report_type','보고서'],['revenue','매출액'],['operating_income','영업이익'],['net_income','당기순이익'],['total_assets','총자산'],['total_liabilities','총부채'],['total_equity','총자본'],['current_assets','유동자산'],['current_liabilities','유동부채'],['cash','현금및현금성자산'],['ppe','유형자산'],['receivables','매출채권'],['inventory','재고자산'],['cfo','영업활동현금흐름'],['operating_margin','영업이익률'],['net_margin','순이익률'],['roe','ROE'],['roa','ROA'],['debt_ratio','부채비율'],['current_ratio','유동비율'],['asset_turnover','총자산회전율']];function table(rows){return `<div class='tablewrap'><table><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${pct.includes(c[0])?p(r[c[0]]):money.includes(c[0])?f(r[c[0]]):(['debt_ratio','current_ratio','asset_turnover'].includes(c[0])?(r[c[0]]==null?'—':Number(r[c[0]]).toFixed(2)):(r[c[0]]??'—'))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}function render(){cards();charts();document.getElementById('annual').innerHTML=table(D.annual);document.getElementById('half').innerHTML=table(D.half_year);document.getElementById('quarter').innerHTML=table(D.quarterly);document.getElementById('peers').innerHTML=`<div class='tablewrap'><table style='min-width:650px'><thead><tr><th>기업</th><th>구분</th><th>종목코드</th><th>비고</th></tr></thead><tbody>${D.peers.map(x=>`<tr><td>${x.name}</td><td>${x.type}</td><td>${x.ticker||'—'}</td><td>${x.note}</td></tr>`).join('')}</tbody></table></div>`}render();</script></body></html>"""
(ROOT/'docs').mkdir(exist_ok=True); (ROOT/'docs/index.html').write_text(html.replace('__DATA__',json.dumps(payload,ensure_ascii=False)),encoding='utf-8')
